import React from "react";

export default function EventCard({ event }) {

  // ✅ Prevent crash if event is undefined
  if (!event) return null;

  return (
    <div className="event-card" style={{ width: "250px" }}>
      
      {/* Show image only if it exists */}
      {event.image_url && (
        <img
          src={event.image_url}
          alt={event.title}
          style={{
            width: "100%",
            height: "160px",
            objectFit: "cover",
            borderRadius: "12px 12px 0 0",
            marginBottom: "12px"
          }}
        />
      )}

      <h3>{event.title}</h3>
      <p>{event.description}</p>

      <button className="event-card-btn">View Event</button>
    </div>
  );
}
